28	/**
29	 * 테스트용 객체 조립기.
30	 *
31	 * - 리포지토리·EntityManager 등 테스트 컨텍스트(@DataJpaTest)에 있는 빈은 그대로 쓴다.
32	 * - com.fream.back.domain 아래의 @Service/@Component 클래스는 실제 객체로 생성자 주입해 만든다.
33	 * - 그 밖의 의존(외부 연동·Redis·WebSocket 등)은 Mockito mock으로 채운다.
34	 * - ApplicationEventPublisher로 발행한 이벤트는 domain 아래 @EventListener/@TransactionalEventListener 메서드로 즉시 전달한다.
35	 */
36	final class Wiring {
37	
38	    private static final String DOMAIN = "com.fream.back.domain";
39	
40	    private final ApplicationContext ctx;
41	    private final Map<Class<?>, Object> instances = new HashMap<>();
42	    private final Set<Class<?>> building = new HashSet<>();
43	    private List<Class<?>> listenerClasses;
