161	    private List<Class<?>> listenerClasses() {
162	        if (listenerClasses == null) {
163	            listenerClasses = new ArrayList<>();
164	            ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
165	            scanner.addIncludeFilter(new AnnotationTypeFilter(Component.class));
166	            scanner.findCandidateComponents(DOMAIN).forEach(bd -> {
167	                try {
168	                    Class<?> c = Class.forName(bd.getBeanClassName());
169	                    for (Method m : c.getDeclaredMethods()) {
