/**
 * 배송 완료된 주문의 구매자에게 주문 총액의 1%를 포인트로 적립하고 혜택 알림을 보냅니다.
 * 주문당 한 번만 적립하며, 1포인트 미만은 버리고 0포인트면 적립하지 않습니다.
 *
 * @param order 배송 완료된 주문
 */
private void grantPurchaseReward(Order order) {
    if (order.isPointRewarded()) {
        log.debug("구매 적립 이미 지급됨: orderId={}", order.getId());
        return;
    }
    order.markPointRewarded();

    int points = order.getTotalAmount() / 100;
    if (points <= 0) {
        log.debug("구매 적립 포인트 없음: orderId={}, totalAmount={}", order.getId(), order.getTotalAmount());
        return;
    }

    User buyer = order.getUser();
    pointRepository.save(new Point(buyer, points, "구매 적립"));
    notificationCommandService.createNotification(
            buyer.getId(),
            NotificationCategory.SHOPPING,
            NotificationType.BENEFIT,
            String.format("구매 적립 %,dP가 지급되었습니다. 주문 ID: %d", points, order.getId())
    );

    log.info("구매 적립 지급: userId={}, orderId={}, points={}", buyer.getId(), order.getId(), points);
}

